-- Imágenes para bebidas conocidas y aderezos. SOLO llena productos SIN foto
-- (image IS NULL): no toca lo que ya tiene foto (ej. Coca-Cola) ni platillos.
-- Fotos: Wikimedia Commons (licencias libres). Genéricas/aderezos: SVG dibujado.
-- Idempotente. Al final lista lo que quedó actualizado.
BEGIN;

CREATE TEMP TABLE _img (pat text, img text, ord int) ON COMMIT DROP;

UPDATE restaurante.menu_items m SET image = i.img
FROM _img i
WHERE m.image IS NULL AND m.type = 'drink' AND trim(m.name) ~* i.pat
RETURNING m.id, m.name AS bebida_con_imagen;

CREATE TEMP TABLE _sauce (pat text, img text, ord int) ON COMMIT DROP;

-- Primer patrón que calce (por orden); si ninguno, color de respaldo.
UPDATE restaurante.menu_items m SET image = (
  SELECT s.img FROM _sauce s WHERE m.name ~* s.pat ORDER BY s.ord LIMIT 1)
WHERE m.image IS NULL AND m.grupo = 'Aderezos'
RETURNING m.id, m.name AS aderezo_con_imagen;

COMMIT;
